files.content:
.wrapper {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  cursor: pointer;
  user-select: none;
}

.control {
  width: 28px;
  height: 28px;
  border: 2px solid var(--border);
  border-radius: var(--choice-radius, 3px);
  appearance: none;
  outline: none;
  margin: 0;
  cursor: pointer;
  position: relative;
  background-color: var(--bg-primary);
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.control::before {
  content: "";
  width: 16px;
  height: 16px;
  background-color: var(--success);
  border-radius: var(--choice-mark-radius, 0);
  position: absolute;
  top: 4px;
  left: 4px;
  display: block;
  transform: scale(0);
  transition: 120ms transform ease-in-out;
}

.control:checked::before {
  transform: scale(1);
}

.control:hover:not(:disabled) {
  border-color: var(--success);
}

.control:focus-visible {
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--success) 25%, transparent);
}

.control:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.label {
  font-family: var(--font-mono);
  font-size: 0.875rem;
  color: var(--text-primary);
}


.radio { --choice-radius: 50%; --choice-mark-radius: 50%; }
.wrapper:has(input:disabled) { cursor: not-allowed; }
@media (prefers-reduced-motion: reduce) {
  .control, .control::before { transition: none; }
}

@media (forced-colors: active) {
  .control { appearance: auto; }
  .control::before { display: none; }
}

.framed { display: flex; align-items: center; min-height: 52px; padding: 12px; }
